typedef int32_t moq_status;
enum {
	MOQ_STATUS_MOVED = 1,
	MOQ_STATUS_EXCLUSIVE = 2,
	MOQ_STATUS_BORROWED = 3,
	MOQ_STATUS_THREAD = 4,
	MOQ_STATUS_LENT = 5,
	MOQ_STATUS_OUTLIVED = 6,
	MOQ_STATUS_NOT_SEND = 7,
};
const char *moq_status_message(moq_status status);
typedef struct moq_buf {
	const uint8_t *ptr;
	size_t len;
	void *owner;
} moq_buf;
void moq_buf_free(moq_buf buf);
